package com.ethk3.novaonepro.r952;
import java.security.MessageDigest;import java.util.*;
public final class ResumableSha256CP12Test {
 static int checks;static void ok(boolean x){checks++;if(!x)throw new AssertionError("SHA "+checks);}static String H(byte[] b)throws Exception{StringBuilder s=new StringBuilder();for(byte x:MessageDigest.getInstance("SHA-256").digest(b))s.append(String.format("%02x",x));return s.toString();}
 public static void main(String[] args)throws Exception{Random random=new Random(12345678);for(int n:new int[]{0,1,2,55,56,63,64,65,127,128,129,1024,65536,10038295}){byte[] data=new byte[n];random.nextBytes(data);ResumableSha256CP12 state=new ResumableSha256CP12();int consumed=0;while(consumed<n){int size=Math.min(n-consumed,1+random.nextInt(8192));state.update(data,consumed,size);consumed+=size;state=ResumableSha256CP12.restore(state.checkpoint(),consumed);ok(state.byteCount()==consumed);}ok(state.digestHex().equals(H(data)));ok(state.digestHex().equals(state.digestHex()));}ResumableSha256CP12 s=new ResumableSha256CP12();byte[] broken=s.checkpoint();broken[broken.length-1]=1;try{ResumableSha256CP12.restore(broken,0);throw new AssertionError("padding accepted");}catch(IllegalArgumentException e){ok(e.getMessage().equals("ATOM_SHA_STATE_PADDING"));}System.out.println("CP12_RESUMABLE_SHA256_PASS checks="+checks+" reference=JCA_SHA256 maxBytes=10038295 checkpointResume=PASS");}
}
